toolScript:
(() => {
  let originalImage = null;
  let currentStyle = 'blackout';
  let isDrawing = false;
  let startX = 0;
  let startY = 0;
  let history = [];

  const dropzone = document.getElementById('sec-dropzone');
  const fileInput = document.getElementById('sec-file-input');
  const browseBtn = document.getElementById('sec-browse-btn');
  const workspace = document.getElementById('sec-workspace');
  const canvas = document.getElementById('sec-canvas');
  const ctx = canvas.getContext('2d');

  const btnBlackout = document.getElementById('sec-style-blackout');
  const btnBlur = document.getElementById('sec-style-blur');
  const btnPixelate = document.getElementById('sec-style-pixelate');
  const btnUndo = document.getElementById('sec-undo-btn');
  const btnClear = document.getElementById('sec-clear-btn');
  const btnCopy = document.getElementById('sec-copy-btn');
  const btnDownload = document.getElementById('sec-download-btn');

  const textInput = document.getElementById('sec-text-input');
  const secretResultsBox = document.getElementById('sec-secret-results');
  const secretListEl = document.getElementById('sec-secret-list');

  function setStyle(style) {
    currentStyle = style;
    [btnBlackout, btnBlur, btnPixelate].forEach(b => {
      b.className = 'px-3 py-1.5 rounded-lg border border-slate-300 bg-white text-slate-700 font-bold text-xs hover:bg-slate-100';
    });
    if (style === 'blackout') btnBlackout.className = 'px-3 py-1.5 rounded-lg bg-slate-900 text-white font-bold text-xs shadow-sm';
    if (style === 'blur') btnBlur.className = 'px-3 py-1.5 rounded-lg bg-slate-900 text-white font-bold text-xs shadow-sm';
    if (style === 'pixelate') btnPixelate.className = 'px-3 py-1.5 rounded-lg bg-slate-900 text-white font-bold text-xs shadow-sm';
  }

  btnBlackout.addEventListener('click', () => setStyle('blackout'));
  btnBlur.addEventListener('click', () => setStyle('blur'));
  btnPixelate.addEventListener('click', () => setStyle('pixelate'));

  function saveHistory() {
    history.push(ctx.getImageData(0, 0, canvas.width, canvas.height));
    if (history.length > 20) history.shift();
  }

  function loadFile(file) {
    if (!file || !file.type.startsWith('image/')) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        originalImage = img;
        canvas.width = img.width;
        canvas.height = img.height;
        ctx.drawImage(img, 0, 0);
        history = [ctx.getImageData(0, 0, canvas.width, canvas.height)];
        dropzone.classList.add('hidden');
        workspace.classList.remove('hidden');
      };
      img.src = e.target.result;
    };
    reader.readAsDataURL(file);
  }

  window.addEventListener('paste', (e) => {
    const items = e.clipboardData ? e.clipboardData.items : [];
    for (const item of items) {
      if (item.type.startsWith('image/')) {
        const file = item.getAsFile();
        loadFile(file);
        break;
      }
    }
  });

  browseBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    fileInput.click();
  });
  dropzone.addEventListener('click', () => fileInput.click());
  fileInput.addEventListener('change', () => {
    if (fileInput.files && fileInput.files[0]) loadFile(fileInput.files[0]);
  });

  dropzone.addEventListener('dragover', (e) => e.preventDefault());
  dropzone.addEventListener('drop', (e) => {
    e.preventDefault();
    if (e.dataTransfer.files && e.dataTransfer.files[0]) loadFile(e.dataTransfer.files[0]);
  });

  function getCanvasCoords(e) {
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    return {
      x: (e.clientX - rect.left) * scaleX,
      y: (e.clientY - rect.top) * scaleY,
    };
  }

  canvas.addEventListener('mousedown', (e) => {
    if (!originalImage) return;
    isDrawing = true;
    const c = getCanvasCoords(e);
    startX = c.x;
    startY = c.y;
    saveHistory();
  });

  canvas.addEventListener('mousemove', (e) => {
    if (!isDrawing) return;
    const c = getCanvasCoords(e);
    const curX = c.x;
    const curY = c.y;
    const x = Math.min(startX, curX);
    const y = Math.min(startY, curY);
    const w = Math.abs(curX - startX);
    const h = Math.abs(curY - startY);

    // Restore last state before previewing
    if (history.length > 0) {
      ctx.putImageData(history[history.length - 1], 0, 0);
    }

    // Live preview border
    ctx.strokeStyle = '#EE6C4D';
    ctx.lineWidth = 2;
    ctx.setLineDash([4, 4]);
    ctx.strokeRect(x, y, w, h);
    ctx.setLineDash([]);
  });

  function applyMask(x, y, w, h) {
    if (w < 2 || h < 2) return;

    if (currentStyle === 'blackout') {
      ctx.fillStyle = '#000000';
      ctx.fillRect(x, y, w, h);
    } else if (currentStyle === 'blur') {
      const imgData = ctx.getImageData(x, y, w, h);
      // Quick multi-pass box blur for high performance
      const d = imgData.data;
      for (let i = 0; i < d.length; i += 4) {
        d[i] = (d[i] + 128) / 2;
        d[i + 1] = (d[i + 1] + 128) / 2;
        d[i + 2] = (d[i + 2] + 128) / 2;
      }
      ctx.putImageData(imgData, x, y);
      // Overlay heavy blurred backdrop
      ctx.fillStyle = 'rgba(15, 23, 42, 0.85)';
      ctx.fillRect(x, y, w, h);
    } else if (currentStyle === 'pixelate') {
      const pixelSize = Math.max(8, Math.round(Math.min(w, h) / 6));
      for (let py = y; py < y + h; py += pixelSize) {
        for (let px = x; px < x + w; px += pixelSize) {
          const pw = Math.min(pixelSize, x + w - px);
          const ph = Math.min(pixelSize, y + h - py);
          const pData = ctx.getImageData(px, py, 1, 1).data;
          ctx.fillStyle = `rgb(${pData[0]},${pData[1]},${pData[2]})`;
          ctx.fillRect(px, py, pw, ph);
        }
      }
    }
  }

  canvas.addEventListener('mouseup', (e) => {
    if (!isDrawing) return;
    isDrawing = false;
    const c = getCanvasCoords(e);
    const x = Math.min(startX, c.x);
    const y = Math.min(startY, c.y);
    const w = Math.abs(c.x - startX);
    const h = Math.abs(c.y - startY);

    if (history.length > 0) {
      ctx.putImageData(history[history.length - 1], 0, 0);
    }
    applyMask(x, y, w, h);
  });

  btnUndo.addEventListener('click', () => {
    if (history.length > 1) {
      history.pop();
      ctx.putImageData(history[history.length - 1], 0, 0);
    } else if (originalImage) {
      ctx.drawImage(originalImage, 0, 0);
    }
  });

  btnClear.addEventListener('click', () => {
    if (originalImage) {
      ctx.drawImage(originalImage, 0, 0);
      history = [ctx.getImageData(0, 0, canvas.width, canvas.height)];
    }
  });

  btnCopy.addEventListener('click', () => {
    canvas.toBlob((blob) => {
      if (!blob) return;
      if (navigator.clipboard && navigator.clipboard.write) {
        const item = new ClipboardItem({ 'image/png': blob });
        navigator.clipboard.write([item]).then(() => {
          alert('Redacted screenshot copied to clipboard!');
        }).catch(() => {
          alert('Clipboard write blocked by browser permission. Use Download PNG.');
        });
      } else {
        alert('Direct clipboard write unsupported in this browser. Use Download PNG.');
      }
    }, 'image/png');
  });

  btnDownload.addEventListener('click', () => {
    const link = document.createElement('a');
    link.download = `redacted_screenshot_${Date.now()}.png`;
    link.href = canvas.toDataURL('image/png');
    link.click();
  });

  // Accompanying Text Scanner
  const PATTERNS = [
    { name: 'OpenAI API Key', regex: /\b(sk-(?:proj-)?[a-zA-Z0-9_-]{40,})\b/g },
    { name: 'Anthropic API Key', regex: /\b(sk-ant-[a-zA-Z0-9_-]{30,})\b/g },
    { name: 'AWS Access Key ID', regex: /\b(AKIA[0-9A-Z]{16})\b/g },
    { name: 'GitHub Token', regex: /\b(ghp_[a-zA-Z0-9]{36}|github_pat_[a-zA-Z0-9_]{50,})\b/g },
    { name: 'Private Key Block', regex: /-----BEGIN [A-Z\s]+PRIVATE KEY-----/g },
  ];

  textInput.addEventListener('input', () => {
    const text = textInput.value;
    const found = [];
    for (const p of PATTERNS) {
      const matches = text.matchAll(p.regex);
      for (const m of matches) {
        found.push({ name: p.name, val: m[0] });
      }
    }
    if (found.length > 0) {
      secretResultsBox.classList.remove('hidden');
      secretListEl.innerHTML = found.map(f => `
        <li class="p-2 rounded bg-rose-50 border border-rose-200 text-rose-900 font-mono flex justify-between">
          <strong>${f.name}</strong>
          <span>${f.val.slice(0, 6)}...[REDACTED]</span>
        </li>
      `).join('');
    } else {
      secretResultsBox.classList.add('hidden');
    }
  });
})();
